set -u
cd /srv/wizard/project
echo "=== BASE STATE ==="
df -h /srv/wizard | tail -1
ls -i target/release/w1z4rd_brain_server 2>&1
cat > /tmp/deploy.b64 <<'B64EOF'

B64EOF
base64 -d /tmp/deploy.b64 > /tmp/deploy.patch
echo "patch bytes: $(wc -c < /tmp/deploy.patch)"
echo "=== APPLY CHECK ==="
if ! git apply --check /tmp/deploy.patch 2>&1; then
  echo "APPLY_CHECK_FAILED"; exit 3
fi
git apply /tmp/deploy.patch 2>&1 || { echo "APPLY_FAILED"; exit 4; }
echo "APPLIED_OK"
chown ec2-user:ec2-user crates/brain/src/store/wbrain_store.rs crates/brain/src/store/container.rs scripts/programming_curriculum_supervisor.py scripts/aws/wizard-curriculum-supervisor.service
echo "=== MARKERS IN SOURCE ==="
echo "clean_skips: $(grep -c clean_skips crates/brain/src/store/wbrain_store.rs)"
echo "append_neuron_body: $(grep -c append_neuron_body crates/brain/src/store/container.rs)"
echo "replay_disk_floor: $(grep -c replay_disk_floor_breached scripts/programming_curriculum_supervisor.py)"
echo "DISK_EXHAUSTED_EXIT: $(grep -c DISK_EXHAUSTED_EXIT scripts/programming_curriculum_supervisor.py)"
echo "=== PY SYNTAX ==="
sudo -u ec2-user python3 -c "import ast,sys; ast.parse(open('scripts/programming_curriculum_supervisor.py').read()); print('supervisor parses')" 2>&1
echo "=== BUILD ==="
sudo -u ec2-user env PATH="/home/ec2-user/.cargo/bin:$PATH" cargo build --release --bin w1z4rd_brain_server 2>&1 | tail -25
echo "=== BUILT BINARY ==="
ls -i --time-style=full-iso -l target/release/w1z4rd_brain_server 2>&1
df -h /srv/wizard | tail -1
